def expandBraces(s: str) -> list[str]:
    groups = []
    i = 0
    while i < len(s):
        if s[i] == '{':
            j = s.index('}', i)
            groups.append(sorted(s[i + 1:j].split(',')))
            i = j + 1
        else:
            groups.append([s[i]])
            i += 1
    res = []
    def backtrack(idx, path):
        if idx == len(groups):
            res.append(''.join(path))
            return
        for opt in groups[idx]:
            backtrack(idx + 1, path + [opt])
    backtrack(0, [])
    return res

